285	    protected boolean giveBirth(int BREEDING_AGE) {
286	        Field field = getField();
287	        List<Location> adjacent = field.adjacentLocations(getLocation());
288	        Iterator<Location> it = adjacent.iterator();
289	        while(it.hasNext()) {
