370	        int breedingAge = getBreedingAge();
371	        if (giveBirth(breedingAge)) {
372	            Field field = getField();
373	            List<Location> free = field.getFreeAdjacentLocations(getLocation());
374	            int births = breed(breedingAge, getBreedingProbability(), getMaxLitterSize());
375	            for (int b = 0; b < births && free.size() > 0; b++) {
