398	    /**
399	     * Look for food adjacent to the current location.
400	     * Only the first live food source is eaten. Other plants may be trampled.
401	     * @return where food was found, or null if it wasn't.
402	     */
403	    private Location findFood() {
404	        if(!canFindFood()) {
405	            return null;
406	        }
407	
408	        Field field = getField();
409	        List<Location> adjacent = field.adjacentLocations(getLocation());
410	        Iterator<Location> it = adjacent.iterator();
411	        while(it.hasNext()) {
412	            Location where = it.next();
413	            Object object = field.getObjectAt(where);
414	            FoodSource foodSource = foodSourceFor(object);
415	
416	            if(foodSource != null && isAliveFood(object)) {
417	                setDeadFood(object);
418	                setFoodLevel(foodSource.getFoodValue());
419	                return where;
420	            }
421	            else if(canTramplePlants() && object instanceof Plant) {
422	                Plant plant = (Plant) object;
423	                if(plant.isAlive()) {
424	                    plant.setDead();
425	                    return where;
426	                }
427	            }
428	        }
429	        return null;
430	    }

